  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"ta","account_id":"acc-A","pnl":-100,"date":"2026-03-10T10:00:00.000Z"},{"id":"tc","account_id":"acc-C","pnl":-5000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-C","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":false,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"ta","account_id":"acc-A","pnl":-100,"date":"2026-03-10T10:00:00.000Z"},{"id":"tc","account_id":"acc-C","pnl":-5000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_res := public.hard_stop_prefs_config_decide('UTC', 'Asia/Ho_Chi_Minh', v_any);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('timezone change when only an off account (no effectiveLimit) is breached' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- prefs timezone change when no account is locked
  v_any := false;
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"ta","account_id":"acc-A","pnl":-100,"date":"2026-03-10T10:00:00.000Z"},{"id":"tb","account_id":"acc-B","pnl":-200,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-B","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"ta","account_id":"acc-A","pnl":-100,"date":"2026-03-10T10:00:00.000Z"},{"id":"tb","account_id":"acc-B","pnl":-200,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_res := public.hard_stop_prefs_config_decide('UTC', 'Asia/Ho_Chi_Minh', v_any);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('timezone change when no account is locked' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- prefs timezone unchanged after normalisation while locked
  v_any := false;
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_res := public.hard_stop_prefs_config_decide('UTC', ' UTC ', v_any);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('timezone unchanged after normalisation while locked' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- prefs timezone change is judged in the OLD timezone
  v_any := false;
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"ta","account_id":"acc-A","pnl":-1000,"date":"2026-03-09T17:10:00.000Z"}]'::jsonb, 'Asia/Ho_Chi_Minh', NULL, NULL, NULL, '2026-03-09T17:30:00Z'::timestamptz)->>'status') = 'locked', false);
  v_res := public.hard_stop_prefs_config_decide('Asia/Ho_Chi_Minh', 'UTC', v_any);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'false' AND (v_res->>'code') IS NOT DISTINCT FROM 'HARD_STOP_CONFIG_LOCKED', false) THEN
    v_fail := v_fail || ('timezone change is judged in the OLD timezone' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- account P5 new trading day: raising maxDailyLoss allowed (lock expired)
  v_lock := (public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-09T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked';
  v_res := public.hard_stop_config_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":5000,"maxDailyLossType":"$"}}'::jsonb, v_lock);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 new trading day: raising maxDailyLoss allowed (lock expired)' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- account P5 maxDailyLoss -> non-number string while locked
  v_lock := (public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked';
  v_res := public.hard_stop_config_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":"5000","maxDailyLossType":"$"}}'::jsonb, v_lock);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'false' AND (v_res->>'code') IS NOT DISTINCT FROM 'HARD_STOP_CONFIG_LOCKED', false) THEN
    v_fail := v_fail || ('P5 maxDailyLoss -> non-number string while locked' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- account P5 reset 17:00 ET: locked yesterday-session, new session after 17:00 ET allows loosening
  v_lock := (public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","resetTime":"17:00","resetTz":"America/New_York"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-01-13T15:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-01-13T22:30:00Z'::timestamptz)->>'status') = 'locked';
  v_res := public.hard_stop_config_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","resetTime":"17:00","resetTz":"America/New_York"}}'::jsonb, '{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":5000,"maxDailyLossType":"$","resetTime":"17:00","resetTz":"America/New_York"}}'::jsonb, v_lock);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 reset 17:00 ET: locked yesterday-session, new session after 17:00 ET allows loosening' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- prefs P5 prefs timezone change on the next day (lock expired) allowed
  v_any := false;
  v_any := v_any OR coalesce((public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-09T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked', false);
  v_res := public.hard_stop_prefs_config_decide('UTC', 'Asia/Ho_Chi_Minh', v_any);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'true' AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 prefs timezone change on the next day (lock expired) allowed' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  -- account P5 percent: initial_balance lowered to 0 while locked (limit <= 0 = removed) blocked
  v_lock := (public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":2,"maxDailyLossType":"%"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz)->>'status') = 'locked';
  v_res := public.hard_stop_config_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":2,"maxDailyLossType":"%"}}'::jsonb, '{"id":"acc-A","initial_balance":0,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":2,"maxDailyLossType":"%"}}'::jsonb, v_lock);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'allowed') = 'false' AND (v_res->>'code') IS NOT DISTINCT FROM 'HARD_STOP_CONFIG_LOCKED', false) THEN
    v_fail := v_fail || ('P5 percent: initial_balance lowered to 0 while locked (limit <= 0 = removed) blocked' || ': ' || coalesce(v_res::text, 'NULL'));
  END IF;
  IF cardinality(v_fail) > 0 THEN
    RAISE EXCEPTION 'hard_stop_config_lock golden FAIL %/%: %', cardinality(v_fail), v_run, array_to_string(v_fail, E'\n');
  END IF;
  IF v_run <> 29 THEN
    RAISE EXCEPTION 'hard_stop_config_lock golden ran % cases, expected 29', v_run;
  END IF;
  RAISE NOTICE 'hard_stop_config_lock golden PASS %/%', v_run, v_run;
END
$golden$;
